F = os.path.join(ROOT, "data", "regions", "vn-lam-dong.json")

REG = "vn-lam-dong"
REGION_NAME_VI = "Lâm Đồng"
FED = "Miền Trung"
TODAY = "2026-07-27"


def maps_for(name_en, lat, lon):
    q = urllib.parse.quote(f"{name_en}, Lâm Đồng, Vietnam")
    return {
        "yandex": f"https://yandex.com/maps/?text={q}&ll={lon},{lat}&z=17",
        "google": f"https://www.google.com/maps/search/?api=1&query={q}",
    }


def rec(slug, name_vi, name_en, name_ru, cats, lat, lon, address_vi, rating,
        review_summary_vi, ps_vi, ps_en, ps_ru, pl_vi, pl_en, pl_ru,
        hi_vi, hi_en, hi_ru, practical, tags):
    return {
        "id": f"{REG}-{slug}", "slug": slug, "region": REG, "country": "vietnam",
        "region_name_vi": REGION_NAME_VI, "federal_district": FED,
        "name_vi": name_vi, "name_ru": name_ru, "name_en": name_en,
        "categories": cats, "coordinates": {"lat": lat, "lon": lon},
        "address_vi": address_vi, "rating": rating,
        "review_summary_vi": review_summary_vi,
        "presentation_short_vi": ps_vi, "presentation_short_en": ps_en,
        "presentation_short_ru": ps_ru, "presentation_long_vi": pl_vi,
        "presentation_long_en": pl_en, "presentation_long_ru": pl_ru,
        "highlights_vi": hi_vi, "highlights_en": hi_en, "highlights_ru": hi_ru,
        "practical": practical, "photo": None, "photo_credit": None,
        "maps": maps_for(name_en, lat, lon), "official_site": None, "sources": [],
        "tags": tags, "status": "enriched", "last_updated": TODAY,
    }


def rt(v, c):
    return {"value": v, "count": c, "source": "Google", "as_of": "2026-07"}


